// 开始回执与完成回执分别引用真实原Action/业务事实，裁剪后仍不准新请求换挂旧成交。
#include "task_shop_order_cached_receipt.hpp"
#include "resident/kernel/command_types.hpp"
#include <charconv>
#include <set>
namespace hanmo::resident {namespace {
std::optional<Integer> serial(const StableId& id,const StableId& prefix,Integer next){const auto head=prefix+":";if(id.rfind(head,0)!=0)return {};const auto text=id.substr(head.size());Integer n=0;auto parsed=std::from_chars(text.data(),text.data()+text.size(),n);if(parsed.ec!=std::errc{}||parsed.ptr!=text.data()+text.size()||n<1||n>=next||std::to_string(n)!=text)return {};return n;}
bool domain_fact(const StableId& id){for(const char* prefix:{task_shop_order_acceptance_prefix,task_shop_order_settled_kind,task_shop_order_interrupted_kind})if(id.rfind(StableId{prefix}+":",0)==0)return true;return false;}
struct Completion {StableId task,fact,code;Integer tick=-1;bool success=false;};
std::map<StableId,Completion> action_sources(const TaskShopOrderState& state){std::map<StableId,Completion> out;for(const auto& row:state.actions.rows())out.emplace(row.first,Completion{row.second.task_id,{},{},-1,false});for(const auto& row:state.settlements.rows())if(row.second.outcome=="delivered")out.emplace(row.second.source_action_id,Completion{row.second.task_id,row.first,{},row.second.tick,true});for(const auto& row:state.interruptions.rows())out.emplace(row.second.source.action_id,Completion{row.second.source.task_id,row.first,row.second.code,row.second.tick,false});return out;}
// 完成发生在本次advance/plan子事务内；后来的同tick结果也不能再次领取其永久事实。
Status completion_interval(const CommonStore& common,const StableId& key,const CommitResult& result,const Completion& source){const auto split=key.rfind(':');if(split==StableId::npos)return common_failure("InvalidTaskShopOrderCacheKey",key);const auto actor=key.substr(0,split),digits=key.substr(split+1);Integer request=0;auto parsed=std::from_chars(digits.data(),digits.data()+digits.size(),request);const auto* sequence=common.state().request_sequences.find(actor);if(!common.actor(actor)||!sequence||digits.empty()||parsed.ec!=std::errc{}||parsed.ptr!=digits.data()+digits.size()||request<1||request>2147483647||request>*sequence||std::to_string(request)!=digits)return common_failure("InvalidTaskShopOrderCacheKey",key);const HistoryRecord* previous=nullptr;const HistoryRecord* lower=nullptr;bool found=false;for(const auto& row:common.state().history){if(row.result_id==result.result_id){if(found||row.tick!=result.tick||row.kind!=result.kind||row.actor_id!=actor)return common_failure("TaskShopOrderCompletionHistoryMismatch");found=true;lower=previous;}previous=&row;}if(!found)return common_failure("TaskShopOrderCompletionHistoryMismatch");const auto next=common.state().next_instance_id;auto from=lower?serial(lower->result_id,"result",next):std::optional<Integer>{0},to=serial(result.result_id,"result",next),fact=serial(source.fact,source.success?task_shop_order_settled_kind:task_shop_order_interrupted_kind,next);if(!from||!to||!fact||*from>=*fact||*fact>=*to||source.tick!=result.tick)return common_failure("TaskShopOrderCompletionAllocationMismatch");return common_success();}
}
Status validate_task_shop_order_cached_results(const CommonStore& common,const TaskState& tasks,const TaskShopOrderState* state){
    if(state){auto valid=validate_task_shop_order_ledger(common,tasks,*state);if(!valid.ok)return valid;}
    for(const auto& row:common.state().history)if(is_task_shop_order_command_kind(row.kind)&&!state)return common_failure("TaskShopOrderProfileRequired",row.result_id);
    const auto known=state?action_sources(*state):std::map<StableId,Completion>{};std::set<StableId> commands,completions;
    for(const auto& row:common.state().results.rows())if(row.second){const auto& result=*row.second;const auto* effect=result.details?std::get_if<InteractionEffect>(&result.details->data):nullptr;const auto* started=result.details?std::get_if<ActionStarted>(&result.details->data):nullptr;const bool command=is_task_shop_order_command_kind(result.kind),fact=effect&&domain_fact(effect->settlement_result),action=started&&known.count(started->action_id);
        if(command||fact||action){if(!state||!command||!result.ok)return common_failure("InvalidTaskShopOrderReceipt",row.first);StableId origin;
            if(result.kind=="task_shop_order_deliver"){if(!started||!action)return common_failure("InvalidTaskShopOrderReceipt",row.first);origin=started->action_id;}
            else {if(!effect||!fact||!effect->encounter_id.empty()||effect->party_id||effect->person_id||effect->news_ids)return common_failure("InvalidTaskShopOrderReceipt",row.first);origin=effect->settlement_result;}
            if(!commands.insert(origin).second)return common_failure("DuplicateTaskShopOrderCachedSource",row.first);auto valid=validate_task_shop_order_cached_source(common,tasks,*state,row.first,result.kind,result.result_id,result.tick,origin);if(!valid.ok)return valid;
        }
        const auto* advance=result.details?std::get_if<AdvanceDetails>(&result.details->data):nullptr;if(!advance)continue;
        for(const auto& entry:advance->completed_actions.rows()){const auto& actual=entry.second;const auto source=known.find(entry.first);const bool own_task=state&&actual.task&&actual.task->task_id&&state->by_task.count(*actual.task->task_id);if(source==known.end()&&!own_task)continue;if(!state||(result.kind!="advance"&&result.kind!="player_plan_step")||source==known.end()||source->second.fact.empty()||!result.ok||!actual.ok||actual.completed||actual.success||actual.already_completed||actual.code||actual.military||actual.family||actual.growth||!actual.task||actual.task->task_id!=std::optional<StableId>{source->second.task}||actual.task->success!=source->second.success||actual.task->on_unavailable||actual.task->retry||actual.task->code!=(source->second.code.empty()?std::optional<StableId>{}:std::optional<StableId>{source->second.code}))return common_failure("InvalidTaskShopOrderCompletionReceipt",entry.first);if(!completions.insert(source->second.fact).second)return common_failure("DuplicateTaskShopOrderCompletionSource",entry.first);auto valid=completion_interval(common,row.first,result,source->second);if(!valid.ok)return valid;}
    }
    return common_success();
}
}
